{
  "identity": {
    "name": "Ascending IT (also styled as Ascending-IT)",
    "location": "2128 N Devlin Way, Nampa, ID 83687 (serving the Boise / Treasure Valley area and nationwide)",
    "claims": [
      {
        "statement": "The business operates under the name Ascending IT and lists its physical address in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "The company states it is based in the Boise area and serves businesses across the Treasure Valley and nationwide.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Based in Boise, serving businesses locally across the Treasure Valley and nationwide."
      },
      {
        "statement": "The footer copyright notice uses the hyphenated name Ascending-IT.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "© 2026 Ascending-IT | All Rights Reserved | Site by Modern Penguin"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology (Managed IT Services and Cybersecurity)",
    "activities": [
      "Managed IT services and 24/7 monitoring",
      "Cybersecurity services (EDR, MDR, ransomware and phishing protection)",
      "Cloud and SaaS management",
      "IT infrastructure, network, and patch management",
      "Backup and disaster recovery",
      "Co-managed IT services and Virtual CIO (vCIO) consulting",
      "Free IT assessments"
    ],
    "claims": [
      {
        "statement": "Ascending IT provides proactive IT management and cybersecurity for small to medium businesses.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "With 20+ years of experience, Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      },
      {
        "statement": "The company offers 24/7 monitoring, maintenance, and IT helpdesk support.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Our Boise Managed IT Services provide 24/7 monitoring, proactive maintenance, and fast support to reduce downtime, control costs, and keep your business running."
      },
      {
        "statement": "The company provides cloud and SaaS management, backup and disaster recovery, co-managed IT services, and strategy/vCIO support.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/managed-it-support-boise/",
        "quote": "Ensure your cloud platforms and SaaS apps run securely and efficiently, with protection that minimizes downtime and data risk."
      },
      {
        "statement": "Ascending IT is a B2B technology service provider rather than a home-service contractor in HVAC, plumbing, or electrical.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "The company packages its managed IT offerings into Silver, Gold, and Platinum tiers.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Silver Package Gold Package Platinum Package"
      },
      {
        "statement": "The company serves multiple commercial verticals including Healthcare, Construction, Finance & Accounting, Professional Services, Manufacturing, Retail, and Hospitality.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Healthcare Construction Finance & Accounting Professional Services Manufacturing Retail Hospitality"
      },
      {
        "statement": "The website offers a free IT assessment via an online intake form.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/request-it-assessment/",
        "quote": "Understand your IT strengths, risks, and opportunities. And gain actionable insights delivered in just a few business days."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company states it assists clients with regulatory compliance frameworks such as HIPAA and PCI-DSS, though it does not list its own state corporate registration or contractor license numbers on the website.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "From HIPAA to PCI-DSS, and cybersecurity threats to scaling challenges, we provide proactive solutions that give you clarity and confidence."
      }
    ],
    "limitations": "No business registration numbers, corporate entity filings, or professional license identifiers are displayed on the inspected public pages, and the Privacy Policy and Terms pages load their text dynamically via an external script."
  },
  "existingSoftware": [
    {
      "product": "https://ascending-it.com/wp-content/themes/Divi/js/scripts.min.js?ver=4.27.9",
      "purpose": "Website content management theme and frontend scripts",
      "evidence": {
        "statement": "The website loads scripts from paths containing `/wp-content/themes/Divi/` and `/wp-includes/`.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://ascending-it.com/wp-content/themes/Divi/js/scripts.min.js?ver=4.27.9"
      }
    },
    {
      "product": "WordPress with Divi theme and Fluent Forms plugin",
      "purpose": "Website CMS, page builder, and web form submission handling",
      "evidence": {
        "statement": "Based on the `/wp-content/themes/Divi/` and `/wp-content/plugins/fluentform/` script paths, the site runs on WordPress using the Divi theme and Fluent Forms.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "on-sitesvcs.connectboosterportal.com",
      "purpose": "Client payment portal host referenced in the page",
      "evidence": {
        "statement": "The homepage references the external host `on-sitesvcs.connectboosterportal.com` and includes a 'Make A Payment' resource link.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "on-sitesvcs.connectboosterportal.com"
      }
    },
    {
      "product": "ConnectBooster",
      "purpose": "Automated billing and payment portal for managed service providers",
      "evidence": {
        "statement": "The host `on-sitesvcs.connectboosterportal.com` is likely a ConnectBooster billing portal used for client invoice payments.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "onsitesvcs.itclientportal.com",
      "purpose": "Client ticketing portal host referenced in the page",
      "evidence": {
        "statement": "The homepage references the external host `onsitesvcs.itclientportal.com` and includes a 'View Ticket Status' resource link.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "onsitesvcs.itclientportal.com"
      }
    },
    {
      "product": "https://www.googletagmanager.com/gtag/js?id=G-MDX53VR4NQ",
      "purpose": "Website analytics and tag management script",
      "evidence": {
        "statement": "The website loads a script from `googletagmanager.com`.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=G-MDX53VR4NQ"
      }
    },
    {
      "product": "https://cdn-cookieyes.com/client_data/75571865f9d74371b7690cb1/script.js",
      "purpose": "Cookie consent banner management script",
      "evidence": {
        "statement": "The website loads a script from `cdn-cookieyes.com`.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://cdn-cookieyes.com/client_data/75571865f9d74371b7690cb1/script.js"
      }
    },
    {
      "product": "https://policies.termageddon.com/api/embed/VjFrMldVVnpiMUVyT1VWV1puYzlQUT09.js",
      "purpose": "Dynamic legal policy embedding script",
      "evidence": {
        "statement": "The privacy policy page loads an embed script from `policies.termageddon.com`.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/privacy-policy/",
        "quote": "https://policies.termageddon.com/api/embed/VjFrMldVVnpiMUVyT1VWV1puYzlQUT09.js"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company collects IT assessment requests through a web form asking for contact details, endpoint/server count, and data size.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/request-it-assessment/",
      "quote": "Free IT Assessment First Name Last Name Email Phone Endpoints / Servers 1-10 11-50 Over 50 I don't know Data Size (if known) Message SUBMIT"
    },
    {
      "statement": "The company already provides automated threat remediation, SaaS active monitoring, and IT management services as part of its core offering.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/",
      "quote": "*Automated Email Threat Remediation is for 365/Google Workspace"
    }
  ],
  "problems": [
    {
      "problem": "No operational problems relevant to ForgeX's home-service contractor offerings were confirmed on the website.",
      "label": "inference",
      "basis": "Based on https://ascending-it.com/ and https://ascending-it.com/managed-it-support-boise/, Ascending IT is an IT managed services provider with existing payment and ticket portals, not a home-service contractor."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Client ticketing portal (onsitesvcs.itclientportal.com) and payment portal (on-sitesvcs.connectboosterportal.com)",
      "addresses": "Customer support ticket tracking and invoice payment processing",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "Ascending IT is outside ForgeX's target segment of owner-led home-service contractors (HVAC, plumbing, and electrical) and already operates as an IT managed service provider, so no ForgeX solution is recommended."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company is not a fit for ForgeX's segment."
  },
  "humanReview": [
    "No implementation or outreach is recommended; human review is only needed to confirm disqualification in the CRM."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Pursuing an IT Managed Service Provider (MSP) falls outside ForgeX's core home-service contractor specialization and risks misallocating sales and delivery resources."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website does not publish service prices or fee schedules, and no ForgeX solution is recommended because the company is outside ForgeX's target segment."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Principal",
      "Managing Partner",
      "Operations Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ascending-it.com/",
        "usedFor": "Business identity, physical address, core IT/cybersecurity offerings, service packages, external portal hosts, and contact details."
      },
      {
        "url": "https://ascending-it.com/boise-it-company/",
        "usedFor": "Company background, mission, compliance focus, and verification of leadership naming (none found)."
      },
      {
        "url": "https://ascending-it.com/it-support-boise/",
        "usedFor": "Contact details, support hours, and physical location verification."
      },
      {
        "url": "https://ascending-it.com/managed-it-support-boise/",
        "usedFor": "Detailed breakdown of managed IT, cloud, backup, co-managed, and vCIO services."
      },
      {
        "url": "https://ascending-it.com/privacy-policy/",
        "usedFor": "Verification of legal entity disclosures and privacy policy embed script."
      },
      {
        "url": "https://ascending-it.com/terms/",
        "usedFor": "Verification of terms and conditions page."
      },
      {
        "url": "https://ascending-it.com/request-it-assessment/",
        "usedFor": "Lead intake form fields and assessment process details."
      }
    ],
    "limitations": [
      "The website does not name any owners, executives, or managers.",
      "The website does not state employee headcount or service pricing.",
      "The Privacy Policy and Terms pages load their body text dynamically via third-party scripts (`policies.termageddon.com`), so the underlying legal text could not be inspected."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Ascending IT is a B2B Managed IT Services and Cybersecurity provider based in Nampa/Boise, Idaho, rather than an owner-led home-service contractor (HVAC, plumbing, or electrical). Furthermore, as an IT service provider with existing client ticketing and payment portals, it is outside ForgeX's target segment."
  }
}
